"""
    Read a key and value from a line.
    Only splits on first instance of separator.

    :param line: string of text to read.
    :param separator: key-value separator
    """
def read_key_value(line: Any, separator: Any = '=') -> object {
    (key, value) = line.split(separator, 1);
    return (key.strip(), value.strip());
}

"""Affine map from interval [l0, h0] to [l1, h1].
    Broadcasting is used to match corresponding dimensions.
    """
def map_affine(x: Any, l0: Any, h0: Any, l1: Any = 0.0, h1: Any = 1.0) -> object {
    x = l1 + (((x - l0) / (h0 - l0)) * (h1 - l1));
    return x;
}

"""replace (str, old, new[, maxsplit]) -> string

    Return a copy of string str with all occurrences of substring
    old replaced by new. If the optional argument maxsplit is
    given, only the first maxsplit occurrences are replaced.

    """
def replace(s: Any, old: Any, new: Any, maxsplit: Any = 0) -> object {
    return s.replace(old, new, maxsplit);
}

"""Return the ith triplet in a sequence.

    Args:
        seq (str): Sequence
        i (int): 0-based index of the target triplet.

    Returns:
        str: The target triplet.
    """
def _triplet(seq: str, i: int) -> object {
    start = i * 3;
    return seq[start:(start + 3)];
}
